+shader_type spatial;
+render_mode cull_disabled;
+
+// Decorative progress only. The original lesson is the single state authority.
+// No TIME: quiet mode and pause never keep moving through a global shader clock.
+uniform float progress : hint_range(0.0, 1.0) = 0.0;
+uniform vec4 warm_color : source_color = vec4(0.93, 0.72, 0.42, 1.0);
+uniform vec4 cool_color : source_color = vec4(0.38, 0.76, 0.76, 1.0);
+varying float flower_color;
+varying float opening;
+
+void vertex() {
+    opening = smoothstep(0.0, 1.0, clamp(progress * 5.0 - INSTANCE_CUSTOM.r, 0.0, 1.0));
+    float hinge = mix(1.22, 0.12, opening);
+    float angle = INSTANCE_CUSTOM.g * 6.28318530718;
+    mat3 lift = mat3(vec3(cos(hinge), sin(hinge), 0.0),
+                     vec3(-sin(hinge), cos(hinge), 0.0),
+                     vec3(0.0, 0.0, 1.0));
+    mat3 turn = mat3(vec3(cos(angle), 0.0, sin(angle)),
+                     vec3(0.0, 1.0, 0.0),
+                     vec3(-sin(angle), 0.0, cos(angle)));
+    VERTEX = turn * lift * VERTEX;
+    NORMAL = normalize(turn * lift * NORMAL);
+    flower_color = INSTANCE_CUSTOM.b;
+}
+
+void fragment() {
+    vec3 color = mix(warm_color.rgb, cool_color.rgb, flower_color);
+    ALBEDO = color;
+    EMISSION = color * (0.025 + 0.055 * opening);
+    ROUGHNESS = 0.72;
+    METALLIC = 0.0;
+    SPECULAR = 0.18;
+}

@@ -0,0 +1,44 @@
+shader_type spatial;
+render_mode unshaded, cull_disabled;
+
+// All motion is driven by the owning scene. TIME is deliberately unused so
+// pause and reduced animation leave these real geometry batches still.
+uniform float animation_time = 0.0;
+uniform float wing_weight : hint_range(0.0, 1.0) = 0.0;
+uniform float drift_scale : hint_range(0.0, 2.0) = 1.0;
+uniform float emission_strength : hint_range(0.0, 2.0) = 0.35;
+uniform vec4 palette_warm : source_color = vec4(1.0, 0.83, 0.60, 1.0);
+uniform vec4 palette_cool : source_color = vec4(0.52, 0.84, 0.81, 1.0);
+
+varying float color_mix;
+varying float light_breath;
+varying float wing_edge;
+
+void vertex() {
+	float phase = INSTANCE_CUSTOM.r * 6.28318530718;
+	float flight_rate = mix(0.35, 0.65, INSTANCE_CUSTOM.g);
+	float flight = animation_time * flight_rate + phase;
+	vec3 point = VERTEX;
+	wing_edge = clamp(abs(point.x) / 0.30, 0.0, 1.0);
+	if (wing_weight > 0.5) {
+		float fold = 0.55 + sin(animation_time * 7.0 + phase) * 0.55;
+		point.y += abs(point.x) * sin(fold);
+		point.x *= cos(fold);
+	}
+	point += vec3(
+		sin(flight) * 0.9,
+		sin(flight * 1.7) * 0.24,
+		cos(flight * 0.83) * 0.7
+	) * drift_scale;
+	VERTEX = point;
+	color_mix = INSTANCE_CUSTOM.b;
+	light_breath = 0.88 + 0.12 * sin(animation_time * 0.7 + phase);
+}
+
+void fragment() {
+	vec3 tint = mix(palette_warm.rgb, palette_cool.rgb, color_mix);
+	float border = mix(1.0, mix(0.34, 1.0, smoothstep(0.06, 0.28, wing_edge)), wing_weight);
+	ALBEDO = tint * border;
+	EMISSION = tint * emission_strength * light_breath;
+	ROUGHNESS = 0.8;
+}

